	return text
		.replace(/[".,?!:;'[\]{\/}@#$%^&*(→)]/g, '')
		.replace(/-/g, ' ')
		.split(' ')
		.filter((token: string) => token.length > 0)
		.map((token: string) => token.toLowerCase());
}

export const createNGrams = (token: string): Set<string> => {
	const n = 10;
	const nGrams: Set<string> = new Set();
